para.example:
   Esempi di Incremento/Decremento


<?php
echo 'Post-incremento:', PHP_EOL;
$a = 5;
var_dump($a++);
var_dump($a);

echo 'Pre-incremento:', PHP_EOL;
$a = 5;
var_dump(++$a);
var_dump($a);

echo 'Post-decremento:', PHP_EOL;
$a = 5;
var_dump($a--);
var_dump($a);

echo 'Pre-decremento:', PHP_EOL;
$a = 5;
var_dump(--$a);
var_dump($a);
?>


   &example.outputs;


Post-incremento:
int(5)
int(6)
Pre-incremento:
int(6)
int(6)
Post-decremento:
int(5)
int(4)
Pre-decremento:
int(4)
int(4)

sect2.example:
   Esempio di incremento delle stringhe PERL


<?php
echo '== Stringhe alfabetiche ==' . PHP_EOL;
$s = 'W';
for ($n=0; $n<6; $n++) {
    echo ++$s . PHP_EOL;
}
// Le stringhe alfanumeriche si comportano diversamente
echo '== Stringhe alfanumeriche ==' . PHP_EOL;
$d = 'A8';
for ($n=0; $n<6; $n++) {
    echo ++$d . PHP_EOL;
}
$d = 'A08';
for ($n=0; $n<6; $n++) {
    echo ++$d . PHP_EOL;
}
?>


   &example.outputs;


== Stringhe alfabetiche ==
X
Y
Z
AA
AB
AC
== Stringhe alfanumeriche ==
A9
B0
B1
B2
B3
B4
A09
A10
A11
A12
A13
A14

warning.example:
    Stringa alfanumerica convertita in float


<?php
$s = "5d9";
var_dump(++$s);
var_dump(++$s);
?>


    &example.outputs;


string(3) "5e0"
float(6)




     Questo perché il valore "5e0" viene interpretato
     come un float e convertito nel valore 5.0
     prima di essere incrementato.
